'use strict';
const reportSegmentLabels={rightArm:'오른팔',leftArm:'왼팔',trunk:'몸통',rightLeg:'오른다리',leftLeg:'왼다리'};
function currentReportRecord(){return recordForDate(reportDate)||active().measurements[0]||null}
function currentReportAnalysis(){const record=currentReportRecord();return record?R.analyze(record,active().measurements):null}
function activeReportPlan(){const plan=active().reportPlan,latest=active().measurements[0];if(!plan||!latest||plan.date!==latest.date)return null;const analysis=R.analyze(latest,active().measurements);return analysis.goal&&plan.signature===analysis.signature?{...analysis,record:latest,date:latest.date}:null}
function cleanReportPlan(raw){return raw&&typeof raw==='object'&&typeof raw.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(raw.date)&&typeof raw.signature==='string'&&raw.signature.length>0&&raw.signature.length<4000?{date:raw.date,signature:raw.signature}:null}
function applyReportPlan(){const a=active(),record=currentReportRecord(),analysis=currentReportAnalysis();if(!record||!analysis?.goal){toast('분석에 필요한 결과지 정보를 먼저 확인해주세요.');return}if(record.date!==a.measurements[0]?.date){toast('최신 측정 기록을 선택해 추천을 적용해주세요.');return}if(a.prefs.pain){toast('현재 몸 상태에 맞는 운동 범위를 먼저 확인해주세요.');return}a.reportPlan={date:record.date,signature:analysis.signature};if(analysis.focusParts.length){focusPart=analysis.focusParts[0].part;focusView=F.parts[focusPart].view}persist();render();savedToast('인바디 분석을 운동 루틴에 적용했어요.')}
function reportMix(routine){return {strength:routine.days.filter(d=>d.type==='strength').length,cardio:routine.days.filter(d=>d.type==='cardio').length}}
function reportExtraFields(extra={}){
const e=R.sanitizeExtra(extra);
return `<div class="report-form-section"><div class="report-section-title"><h3>추천에 사용하는 결과지 정보</h3><span>사진 인식값을 확인해주세요</span></div><div class="form-grid">${selectField('reportSex','결과지 성별',[['','미입력'],['male','남성'],['female','여성']],e.sex||'')}${field('reportMuscleControl','근육 조절 (선택)',e.muscleControl??'','kg','min="-100" max="100" step="0.1" placeholder="예: +2.0"')}${field('reportFatControl','지방 조절 (선택)',e.fatControl??'','kg','min="-100" max="100" step="0.1" placeholder="예: -3.0"')}</div><p class="report-field-help">‘근육조절’, ‘지방조절’은 결과지의 체중조절 영역에 적힌 증감 수치입니다. +와 − 부호를 그대로 입력하세요. 없는 항목은 비워두세요.</p></div>
<details id="reportRatingDetails" class="report-segment-details" ${Object.values(e.segmentRatings).some(v=>v!==null)?'open':''}><summary>부위별 근육·제지방 평가 문구 <span>표준 이하·표준·표준 이상</span></summary><p class="report-field-help">숫자 비율이 없는 결과지는 <b>부위별 근육분석</b>에 인쇄된 문구를 확인해주세요. 옆의 부위별 체지방분석과 구분합니다.</p><div class="form-grid report-segment-fields">${Object.entries(reportSegmentLabels).map(([key,name])=>selectField('rating'+key[0].toUpperCase()+key.slice(1),name,[['','미입력'],['low','표준 이하'],['normal','표준'],['high','표준 이상']],e.segmentRatings[key]||'')).join('')}</div><label class="check-field"><input id="ratingConfirmed" type="checkbox" ${e.ratingReference==='lean'?'checked':''}> 입력한 평가가 부위별 근육·제지방 분석의 문구임을 확인했어요.</label><p class="report-field-help">‘표준 이하’를 임의의 비율이나 순수 근육량, 실제 근력으로 환산하지 않습니다.</p></details>
<details id="reportSegmentDetails" class="report-segment-details" ${Object.values(e.segments).some(v=>v!==null)?'open':''}><summary>부위별 제지방 비율 확인 <span>숫자 비율이 있을 때만 입력</span></summary><p class="report-field-help">결과지에 두 비율이 있다면 <b>아래쪽의 현재 체중 대비 비율(%)</b>만 사용합니다. kg 값이나 부위별 체지방 비율은 입력하지 마세요. 어떤 비율인지 불명확하면 비워두세요.</p><div class="form-grid report-segment-fields">${Object.entries(reportSegmentLabels).map(([key,name])=>field('seg'+key[0].toUpperCase()+key.slice(1),name,e.segments[key]??'','%','min="40" max="250" step="0.1" placeholder="결과지 수치"')).join('')}</div><label class="check-field"><input id="segmentConfirmed" type="checkbox" ${e.segmentReference==='bodyWeight'?'checked':''}> 입력한 부위별 값이 현재 체중 대비 제지방 비율(%)임을 확인했어요.</label><p class="report-field-help">제지방에는 수분·뼈 등이 포함돼요. 이 값으로 순수 근육량이나 근력, 가슴과 등 각각의 상태를 판정하지 않습니다.</p></details>`}
function readReportForm(){
const optional=(id,min,max)=>{const input=$(id);if(!input||input.value.trim()==='')return null;const n=Number(input.value);if(!Number.isFinite(n)||n<min||n>max)throw new Error(`${id==='reportMuscleControl'?'근육 조절':id==='reportFatControl'?'지방 조절':'부위별 비율'}을 ${min}–${max} 범위의 수치로 확인해주세요.`);return n};
try{
const segments={},segmentRatings={};for(const key of Object.keys(reportSegmentLabels)){segments[key]=optional('seg'+key[0].toUpperCase()+key.slice(1),40,250);const rating=$('rating'+key[0].toUpperCase()+key.slice(1))?.value;segmentRatings[key]=['low','normal','high'].includes(rating)?rating:null;}
if(Object.values(segments).some(v=>v!==null)&&!$('segmentConfirmed')?.checked)return {ok:false,error:'부위별 수치를 입력했다면 현재 체중 대비 제지방 비율인지 확인에 체크해주세요. 불명확한 수치는 비워두세요.'};
if(Object.values(segmentRatings).some(v=>v!==null)&&!$('ratingConfirmed')?.checked)return {ok:false,error:'부위별 평가 문구를 입력했다면 근육·제지방 분석의 값인지 확인에 체크해주세요.'};
return {ok:true,report:R.sanitizeExtra({sex:$('reportSex')?.value||null,muscleControl:optional('reportMuscleControl',-100,100),fatControl:optional('reportFatControl',-100,100),segments,segmentReference:$('segmentConfirmed')?.checked?'bodyWeight':null,segmentRatings,ratingReference:$('ratingConfirmed')?.checked?'lean':null,source:photoInputUsed?'photo':'manual'})}
}catch(error){return {ok:false,error:error.message}}}
function reportPage(){const a=active(),record=currentReportRecord(),analysis=currentReportAnalysis(),applied=activeReportPlan();const latest=record?.date===a.measurements[0]?.date;
let html=pageHeading('사진 속 숫자를,<span class="report-heading-tail"> 나의 운동 기준으로.</span>','인바디 사진을 읽고 확인한 값이 실제 추천으로 이어집니다.',`<button class="btn" data-action="measurement">직접 입력</button><button class="btn primary" data-action="report-photo">${icon('upload')}인바디 사진 올리기</button>`);
html+=`<section class="report-start"><button class="report-upload" id="reportDrop" data-action="report-photo"><span class="report-upload-symbol">${icon('upload')}</span><span><span class="report-kicker">START WITH YOUR RESULT</span><strong>인바디 결과지 사진 한 장으로 시작해요.</strong><small>클릭하거나 여기에 이미지 끌어놓기 · JPG, PNG, WEBP · 최대 10MB</small></span><span class="report-upload-arrow">↗</span></button><div class="report-steps"><span><b>01</b> 사진 읽기</span><span><b>02</b> 수치 확인</span><span><b>03</b> 분석 후 루틴 적용</span></div></section>`;
if(!record)return html+`<div class="report-onboarding"><section class="panel panel-pad"><span class="report-card-number">01</span><h2>무엇을 읽나요?</h2><p>키·나이·체중·골격근량·체지방률과 결과지의 근육·지방 조절 수치를 확인해요.</p></section><section class="panel panel-pad"><span class="report-card-number">02</span><h2>무엇이 달라지나요?</h2><p>확인한 값에 따라 근력·유산소의 주간 구성과 부위별 동작 우선순위를 바꿔요.</p></section><section class="panel panel-pad"><span class="report-card-number">03</span><h2>직접 확인하고 적용해요.</h2><p>읽지 못한 항목은 직접 채우고, 추천 이유를 확인한 다음 내 루틴에 반영해요.</p></section></div><p class="report-bottom-note">사진은 브라우저에서 처리하며 앱 서버에 저장하지 않습니다. 인식 도구·언어 데이터 다운로드에는 인터넷이 필요합니다.</p>`;
const extra=R.sanitizeExtra(record.report),preview=R.generate(record,a.prefs,a.measurements),mix=reportMix(preview.routine),isApplied=applied?.signature===analysis.signature;const canApply=analysis.goal&&latest&&!a.prefs.pain;
html+=`<div class="report-record-bar"><div><span>분석할 기록</span><select id="reportDate" aria-label="분석할 측정일">${a.measurements.map(r=>`<option value="${r.date}" ${r.date===record.date?'selected':''}>${longDate(r.date)}</option>`).join('')}</select><span class="badge ${extra.source==='photo'?'':'neutral'}">${extra.source==='photo'?'사진 확인 기록':'직접 입력 기록'}</span></div><button class="btn ghost small" data-action="edit-measurement" data-date="${record.date}">${icon('edit')}수치·추가 정보 수정</button></div><div class="report-values">${[['체중',record.weight,'kg'],['골격근량',record.muscle,'kg'],['체지방률',record.fat,'%']].map(([name,value,unit])=>`<div><span>${name}</span><strong>${fmt(value)}<small>${unit}</small></strong></div>`).join('')}</div><div class="report-result-layout"><section class="report-strategy"><span class="report-kicker">MY INBODY INSIGHT</span><div class="report-strategy-top"><h2>${esc(analysis.title)}</h2>${isApplied?'<span class="badge">내 루틴에 적용 중</span>':''}</div><p>${esc(analysis.summary)}</p>${analysis.goal?`<div class="report-mix"><div><span>추천 근력 운동</span><strong>${mix.strength}<small>일 / 주</small></strong></div><div><span>추천 유산소 운동</span><strong>${mix.cardio}<small>일 / 주</small></strong></div></div>`:'<div class="report-awaiting">결과지 정보를 보완하면 분석에 따른 주간 구성을 제안합니다.</div>'}<p class="report-mix-note">주 ${a.prefs.days}일 · 1회 ${a.prefs.minutes}분 · ${a.prefs.place==='gym'?'헬스장':a.prefs.equipment==='band'?'집 · 밴드':'집 · 맨몸'} 조건으로 구성합니다.</p>${analysis.missing?.length?`<div class="report-missing"><b>추가로 확인할 정보</b><ul>${analysis.missing.map(m=>`<li>${esc(m)}</li>`).join('')}</ul><button class="btn soft small" data-action="edit-measurement" data-date="${record.date}">결과지 정보 보완하기</button></div>`:''}<div class="report-apply-actions">${isApplied?`<button class="btn primary" data-action="focus-today">적용된 운동 루틴 보기 ${icon('arrow')}</button><button class="btn ghost small" data-action="clear-report">분석 적용 해제</button>`:`<button class="btn primary" data-action="apply-report" ${canApply?'':'disabled'}>이 분석으로 루틴 만들기 ${icon('arrow')}</button>`}</div>${!latest?'<p class="report-mix-note">최신 기록을 선택하면 운동 루틴에 적용할 수 있어요.</p>':''}${a.prefs.pain?'<p class="report-mix-note">운동 조건에 선택한 몸 상태를 먼저 확인해주세요.</p>':''}<p class="report-rules-note">제조사의 운동 처방이 아닌 앱의 규칙 기반 일반 운동 가이드입니다. 확인한 결과지 정보를 운동 구성에 연결합니다.</p></section><section class="panel panel-pad report-evidence"><div class="panel-head"><div><h2>추천의 근거가 된 수치</h2><p>어떤 값이 추천에 쓰였는지 확인하세요.</p></div>${icon('file')}</div>${analysis.evidence.length?analysis.evidence.map(item=>`<div class="report-evidence-row"><div><span>${esc(item.label)}</span><b>${esc(item.value)}</b></div><p>${esc(item.explanation)}</p></div>`).join(''):'<p class="settings-copy">분석에 사용할 결과지의 추가 정보를 확인해주세요.</p>'}</section></div>`;
html+=`<section class="panel panel-pad report-region-panel"><div class="panel-head"><div><h2>부위별 정보와 운동 연결</h2><p>확인한 근육·제지방 평가 문구 또는 체중 대비 비율을 사용합니다.</p></div><button class="btn ghost small" data-action="nav" data-page="focus">바디 맵 보기 ${icon('arrow')}</button></div><div class="report-segment-grid">${Object.entries(reportSegmentLabels).map(([key,name])=>`<div><span>${name}</span><b>${extra.ratingReference==='lean'&&extra.segmentRatings[key]?esc(({low:'표준 이하',normal:'표준',high:'표준 이상'})[extra.segmentRatings[key]]):extra.segmentReference==='bodyWeight'&&extra.segments[key]!==null?`${fmt(extra.segments[key])}<small>%</small>`:'—'}</b><small>${extra.ratingReference==='lean'&&extra.segmentRatings[key]?'결과지 평가 확인값':extra.segmentReference==='bodyWeight'&&extra.segments[key]!==null?'체중 대비 확인값':'확인된 값 없음'}</small></div>`).join('')}</div>${analysis.focusParts.length?`<div class="report-priorities">${analysis.focusParts.map(item=>`<div><span class="report-priority-icon">${icon('body')}</span><div><b>${F.parts[item.part].name} 동작을 먼저 살펴보세요.</b><p>${esc(item.reason)}</p></div><button class="btn soft small" data-action="report-focus" data-part="${item.part}">운동 보기</button></div>`).join('')}</div>`:'<p class="report-bottom-note">확인한 부위별 평가나 비율이 없으면 특정 부위를 추정하지 않습니다. 바디 맵에서 원하는 부위를 직접 선택할 수 있어요.</p>'}<p class="report-bottom-note">팔·다리·몸통의 제지방 정보입니다. 몸통 비율로 가슴·등·어깨 각각의 상태나 근력을 판단하지 않으며 한쪽 운동량을 임의로 늘리지 않습니다.</p></section><div class="report-source-note">참고: <a href="https://uk.inbody.com/wp-content/uploads/2021/01/The-Professionals-Guide-to-the-InBody-Result-Sheet_ENGLISH-rev2.pdf" target="_blank" rel="noopener">InBody 공식 결과지 가이드 ↗</a><a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener">ACSM 운동 가이드 ↗</a></div>`;return html}
function reportRoutineBanner(){const plan=activeReportPlan();if(!plan)return active().reportPlan?`<div class="report-plan-banner stale"><div><b>측정 기록이 바뀌어 이전 분석 적용을 멈췄어요.</b><p>최신 수치를 확인하고 다시 분석을 적용해주세요.</p></div><button class="btn small" data-action="nav" data-page="report">분석 확인</button></div>`:'';return `<div class="report-plan-banner"><div><span>INBODY APPLIED</span><b>${esc(plan.title)}</b><p>${longDate(plan.record.date)} 확인 기록을 운동 구성에 반영 중입니다.${plan.focusParts.length?' '+plan.focusParts.map(item=>F.parts[item.part].name).join('·')+' 동작을 우선 배치했어요.':''}</p></div><button class="btn soft small" data-action="nav" data-page="report">분석 근거 보기</button></div>`}
